 Run("legendary-death-wakes-same-id-one",()=>{var s=Fresh();var b=Barrack("a",3,true);var tie=Barrack("a",3,true);var wrong=Barrack("b",100,true);s.AddLegendaryBarracks("a",true);s.AddLegendaryUnit("a",true);s._enemyWaitingBarracks.AddRange(new[]{b,tie,wrong});b.onSpawn=()=>Check(!s._enemyWaitingBarracks.Contains(b),"removed before callback");s.RemoveLegendaryUnit("a",true);Check(b.spawned==1&&tie.spawned==0&&wrong.spawned==0,"same id first tie");Check(!s._enemyLegendaryUnitCount.ContainsKey("a"),"unit zero key gone");});
 Run("target-list-filters-tie-and-faction",()=>{var s=Fresh();var a=Role(2);var tie=Role(-2);var dead=Role(0,true);var hidden=Role(0,false,true);var yfar=Role(0,false,false,4);s.allEnemyRoleBehaviour.AddRange(new[]{null,dead,hidden,a,tie,yfar});var ally=Role(1);s.allPlayerRoleBehaviour.Add(ally);Check(s.TryGetNearestRoleTarget(new Vector3(0),false,2,out var t)&&t==a,"range inclusive first tie");Check(s.TryGetNearestRoleTarget(new Vector3(0),true,2,out t)&&t==ally,"opposite camp");var found=s.GetRoleTargetsSync(new Transform(),false,10,2);Check(found.SequenceEqual(new[]{a,tie}),"nearest top two");Check(s.GetRoleTargetsSync(new Transform(),false,10,0).Single()==a,"roleNum zero native one-target path");});
 Run("target-result-clearing-and-null",()=>{var s=Fresh();var r=Role(0);s.allEnemyRoleBehaviour.Add(r);var list=new List<RoleBehaviour>{r};Check(s.CollectRoleTargetsInRange(new Vector3(),false,-1,list)==0&&list.Count==0,"negative clears");list.Add(r);Check(s.CollectRoleTargetsInRange((Transform)null,false,1,list)==0&&list.Count==0,"null transform clears");Check(!s.TryGetNearestRoleTarget((Transform)null,false,1,out var t)&&t==null,"null target");Check(s.CollectRoleTargetsInRange(new Vector3(),false,1,null)==0,"null list");list.Add(r);Check(BattleGameSceneManager.CollectRoleTargetsInRangeFromList(new Vector3(),s.allEnemyRoleBehaviour,1,list)==2,"helper appends");});
 Run("target-hex-searched-empty-suppresses-fallback",()=>{var s=Fresh();s.allEnemyRoleBehaviour.Add(Role(0));HexManager.locate=true;HexManager.source=new(){HexCoord=new(5,7)};Check(!s.TryGetNearestRoleTarget(new Vector3(),false,1,out var t)&&t==null,"searched hex empty does not fall back");Check(HexManager.looked.Count==37,"range 1 uses ring 3 = 37 hexes");var list=new List<RoleBehaviour>();Check(s.CollectRoleTargetsInRange(new Vector3(),false,1,list)==0,"collect same fallback gate");});
 Run("target-hex-camp-and-frame-cache",()=>{var s=Fresh();var old=Role(1);var fresh=Role(0.5f);s.allEnemyRoleBehaviour.AddRange(new[]{old,fresh});HexManager.locate=true;var h=new HexBehaviour{HexCoord=new(0,0)};h.enemy.Add(old);HexManager.source=h;HexManager.map[(0,0)]=h;Check(s.TryGetNearestRoleTarget(new Vector3(),false,2,out var t)&&t==old,"hex enemy");h.enemy.Add(fresh);Check(s.TryGetNearestRoleTarget(new Vector3(),false,2,out t)&&t==old,"same frame cached valid target");Time.frameCount++;Check(s.TryGetNearestRoleTarget(new Vector3(),false,2,out t)&&t==fresh,"next frame re-search");fresh.isDead=true;Check(s.TryGetNearestRoleTarget(new Vector3(),false,2,out t)&&t==old,"invalid cached target removed");});
 Run("target-key-buckets-and-ring-fallback",()=>{var s=Fresh();HexManager.locate=true;HexManager.source=new(){HexCoord=new(-2,3)};Check(s.TryGetRoleTargetFrameCacheKey(new Vector3(),true,1.001f,out var k)&&k.q==-2&&k.r==3&&k.sourceIsEnemy&&k.rangeBucket==101,"ceil bucket");var r=Role(1);s.allEnemyRoleBehaviour.Add(r);Check(s.TryGetNearestRoleTarget(new Vector3(),false,100,out var t)&&t==r,"range over 10 rings falls back");Check(!s.TryGetRoleTargetHexSearchRing(100,out int ring)&&ring>10,"ring boundary");});
 Run("target-original-nan-compare-contract",()=>{var s=Fresh();var a=Role(1);var nan=Role(float.NaN);s.allEnemyRoleBehaviour.AddRange(new[]{a,nan});Check(BattleGameSceneManager.TryGetNearestRoleTargetFromList(new Vector3(),s.allEnemyRoleBehaviour,10,out var t)&&t==nan,"native B.GT/B.GE allow unordered distance");var found=new List<RoleBehaviour>();BattleGameSceneManager.CollectRoleTargetsInRangeFromList(new Vector3(),s.allEnemyRoleBehaviour,10,found);Check(found.SequenceEqual(new[]{a}),"native B.HI collection rejects unordered distance");Check(s.TryGetNearestRoleTarget(new Vector3(),false,float.NaN,out t),"native range B.MI allows NaN");});
 string mode=JsonDocument.Parse(File.ReadAllText("extraction.json")).RootElement.GetProperty("mode").GetString();var report=new{mode,scenarios,checks,failed,nativeOperations=2688,results};File.WriteAllText(mode+"-result.json",JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"SCENE_TESTS mode={mode} scenarios={scenarios} checks={checks} failed={failed}");if(failed>0){foreach(dynamic row in results.TakeLast(20))Console.WriteLine(JsonSerializer.Serialize(row));Environment.Exit(1);}
 }
